INSERT INTO feature VALUES('traces','sessions','A run''s channels traced as dialogues','session-machine','implemented','notable',NULL,'A `traces` beside a definition''s `runs` records the run''s plays, each channel the run forks a dialogue of its two endpoints'' moves named by the fork''s protocol binder, and states the web one channel''s play decomposes to, `traces(decomposes(c, series(…)))` or its prime count `traces(primes(c, n))`, written once per channel. The corpus settles a channel as `decomposes` settles a dialogue literal; a channel that plays another web or is never forked leaves the run outcome unsettled, both webs printed. A run without the attribute records nothing.','runtime-emitter core-sequent surface-lowering surface-pretty surface-dispatcher surface-evaluate surface-corpus','corpus/model/tasks/forced.gandr corpus/model/tasks/spoken-first.gandr corpus/model/tasks/independent.gandr corpus/model/sessions/seat-exchange.gandr corpus/ledger/attributes/traces.gandr crates/runtime-emitter/tests/sessions.rs::a_traced_run_plays_each_channel_as_its_dialogue crates/surface-evaluate/src/evaluate.rs::a_traced_run_names_each_channel_by_its_fork_3338 crates/surface-corpus/src/settle.rs::a_channel_settles_against_the_web_its_play_decomposes_to_3338 crates/surface-driver/tests/cli.rs::a_stated_web_the_run_does_not_produce_is_unsettled_3338','corpus/model/tasks/forced.gandr',NULL);
